mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, sys, time, urllib.request, urllib.error

BASE = "http://localhost:8080"
token = None

def req(method, path, auth=False):
    global token
    headers = {}
    if auth:
        if token is None:
            token = get_token()
        headers["Authorization"] = "Bearer " + token
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(r, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()

def get_token():
    st, h, body = req("POST", "/token")
    if st != 200:
        raise RuntimeError(f"token failed {st}: {body[:200]}")
    return json.loads(body)["token"]

def get_json(path, auth=True):
    global token
    attempts = 0
    while True:
        attempts += 1
        if attempts > 200:
            raise RuntimeError(f"giving up on {path}")
        st, h, body = req("GET", path, auth=auth)
        if st == 200:
            return json.loads(body)
        sys.stderr.write(f"{path} -> {st} headers={h} body={body[:200]!r}\n")
        if st == 401 or st == 403:
            token = get_token()
            continue
        if st == 429:
            wait = h.get("Retry-After")
            try:
                w = float(wait)
            except (TypeError, ValueError):
                w = 1.0
            time.sleep(w)
            continue
        if st >= 500:
            time.sleep(1)
            continue
        if st == 404:
            return None
        raise RuntimeError(f"unexpected {st} for {path}")

if __name__ == "__main__":
    out = sys.argv[1]
    pages = []
    page = 1
    total_pages = None
    path = "/orders?page=1"
    while path:
        data = get_json(path)
        pages.append(data)
        path = data.get("next")
        total_pages = data.get("total_pages")
        sys.stderr.write(f"page {data.get('page')} of {total_pages}, items={len(data['items'])}, next={path}\n")
    with open(out, "w") as f:
        json.dump(pages, f)
EOF
cd /tmp/recon && python3 -I fetch.py /tmp/recon/orders_pages.json; echo "exit=$?"

